-- Mod-authored victory and defeat screen descriptions, zh_Hant_HK overlay.
-- Baseline in CivVAccess_VictoryDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_MISSING"] = "此畫面沒有描述."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_CULTURAL"] =
    "在一片由深色樹木遮蔭的青草山丘上, 兩個人影以剪影坐着, 眺望腳下一座金色的城市. 在他們下方, 一群人正走過一座拱形石橋, 橋兩側立着座落於基座上的古典雕像, 一座穹頂大廳在橋後升起. 越過一片綠地, 天際線升入纖細的未來主義高塔, 高塔消融在琥珀色的薄霧中. 人們散布在草坪上: 孩子們在一隻高飛於牽線上的風箏下奔跑, 一個人影撐着黃色陽傘漫步, 白色的船帆在薄霧中遠處的水面上隱現. 整個場景沐浴在溫暖的金色光線中, 半似午後黃昏, 半似夢境, 天空中飛鳥點點."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_DIPLOMATIC"] =
    "一場儀式在聯合國總部高聳的白色板樓前的綠色草坪上舉行. 前景中, 一群人背向觀者站立, 身着來自眾多國家的西裝, 長袍與頭巾, 右側一名電視攝影師在三腳架後拍攝. 旗杆環繞草坪, 懸掛着數十面國旗, 其中可辨認出美國和墨西哥. 中央, 一個巨大的石制地球儀安放在繁茂樹木之下的方形基座上, 其上各大洲以浮雕凸起. 它前方等候着一列身穿不同國家民族服飾的兒童; 一位身着藍衣的女子俯身, 將某物遞給一個身穿黃色裙子, 仰手去接的小女孩. 紅白兩色的花壇圍着畫面底部一池靜水, 柔和的灰色天光將一切映照得均勻平和."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_DOMINATION"] =
    "一場以海報色彩繪成的勝利遊行, 通體金, 橄欖綠與紅色. 右側前景中, 一名身穿白色禮服軍裝, 肩部綴有金色穗帶的年輕軍官緊握着一面巨大紅旗的旗桿, 紅旗橫越天空翻飛, 他的尖頂軍帽鑲着紅色帽帶與金色帽徽. 在他身後, 一排排身着同款白色軍裝的士兵肩扛上了刺刀的步槍直立而站, 更多紅旗從隊列中升起. 遊行隊伍上方, 一座青銅雕像立於高大基座之上, 塑成一位指揮官策馬疾行的姿態, 其後是一座巨大的穹頂議會大廈. 纖細的紅色旗幟如緞帶般在發光的黃綠色天空中飄揚, 深色的柏樹與朦朧的群山封閉了遠景."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_SPACE_RACE"] =
    "深邃的太空, 自下方仰望一座龐大的軌道太空站. 它深色的船身橫貫畫面頂部, 底側排列着一排排高大的暖色照明窗口與綠光閃爍的艙位. 縷縷蒸氣飄過金屬表面. 平展的網格狀太陽能板從船身沿桁架吊臂伸展開來, 一座覆有面板的長形桁架塔從其遠端垂下, 落入畫面右側. 下方, 一顆行星的夜面以深紫與酒紅色向遠處鋪展, 其地平線弧過場景底部. 太陽剛從那地平線上破曉而出, 化作一道白金色的閃光, 照亮沿弧線排列的玫瑰色與奶白色雲帶. 前景中, 一艘孤獨的有翼飛船劃過黑暗, 拖着一道長長發光的青藍色尾跡, 更小的飛行器在遠處映着星空閃出綠色與橙色的光芒."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_VICTORY_TIME"] =
    "遊戲本身的封面藝術放大至填滿整個畫面. 一個由古舊深褐色地圖拼綴而成的地球儀主宰着畫面, 標題Sid Meier's Civilization以拋光金屬的凸起字母橫貫其上, 穿過一個巨大的黃銅羅馬數字五. 一張磨損的芬蘭郵票貼在左上方, 上面一名騎手騎着裝飾華麗的馬匹, 紀念《卡勒瓦拉》史詩. 淡淡的郵戳印於其周圍. 地球儀後方鋪着一片青藍色染漬紙張的拼貼, 一道黃銅子午環弧繞着地球儀的下緣, 光線自左上方灑落, 彷彿一件擺於燈下的珍玩."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_VICTORYDESC_DEFEAT"] =
    "沙漠天空下一個已死的帝國. 一座雕像巨大的石制頭顱側臉躺在沙中, 雙眼緊閉, 面容安詳, 一旁一隻斷裂的石手自地面伸出, 手指向天蜷曲. 一處發掘現場環繞着它: 壕溝切入前景的泥土, 一道由柱與鐵絲組成的圍欄, 一個身着淺色衣物的孤獨人影站在一座木制階梯平台上, 在他所端詳的面容前顯得渺小. 一頭馱獸在左側等候. 空曠的山谷向後延伸, 越過散落的直立殘塊, 直抵地平線上平頂的台地. 在稀薄的藍色天空下, 一切皆呈黃褐與鏽紅之色, 雪萊筆下《奧西曼德斯》那孤寂而平坦的沙原向遠方鋪展而去."
